result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/launch.js", "content": "import * as THREE from 'three';

// ---------------------------------------------------------------------------
// Timeline constants (seconds)
// ---------------------------------------------------------------------------
export const T_IGNITION = 2;   // shake starts
export const T_LIFTOFF  = 3;   // wheels (well, pad) leave
export const T_BLEND    = 5.5; // quadratic eases into linear ascent
export const T_SEP      = 8;   // booster separation

// --- ignition shake ---------------------------------------------------------
export const SHAKE_AMP = 0.05; // metres
export const SHAKE_HZ  = 30;

// --- ascent profile ---------------------------------------------------------
// Phase A (T_LIFTOFF <= t < T_BLEND):   y(s) = A*s^2            with s = t - 3
// Phase B (t >= T_BLEND):               y(s) = V*s + C
//
// Derivation of the blend constants (requirement: C1 continuity at s0 = 2.5,
// i.e. at t = T_BLEND = 5.5):
//
//   Value match at s0:        A*s0^2 = 4*(2.5)^2          = 25 m
//   Slope of phase A at s0:   d/ds [A*s^2] = 2*A*s0 = 8*2.5 = 20 m/s
//
//   The target linear profile is y = 20*s (V = 20 m/s terminal climb rate).
//   To pass through the phase-A endpoint while keeping slope 20 we take the
//   tangent continuation:
//
//     C = y(s0) - V*s0 = 25 - 20*2.5 = -25
//
//   So phase B is  y = 20*s - 25.  Both branches have slope exactly 20 m/s
//   at s0 (phase A's slope tends to 2*A*s0 = 20), hence y and dy/dt are both
//   continuous at t = 5.5 -> C1 holds by construction.
export const QUAD_A    = 4;
export const LINEAR_V  = 20;  // m/s, matched slope  2*A*T_(s0)
export const BLEND_C   = -25; // offset, y(s0) - LINEAR_V*s0 = 25 - 50

// --- separation -------------------------------------------------------------
export const SEP_DRIFT_X = 1.5; // m/s, booster drift along +x after detach
export const GRAVITY     = 9.81; // m/s^2, ballistic deceleration of the booster

// Local y offset of the booster inside the rocket group while attached.
export const BOOSTER_LOCAL_Y = -0.6;

// Rocket velocity during phase B is constant, so the separation velocity at
// t = T_SEP is simply LINEAR_V.
const SEP_V_Y = LINEAR_V;

// ---------------------------------------------------------------------------
// Pure kinematics
// ---------------------------------------------------------------------------

/** Altitude of the rocket at time t (metres). Exact 0 before liftoff. */
export function altitude(t) {
  if (t < T_LIFTOFF) return 0;
  const s = t - T_LIFTOFF;
  if (t < T_BLEND) return QUAD_A * s * s;
  return LINEAR_V * s + BLEND_C;
}

/** Signed shake displacement in the ignition window, else 0. */
export function shake(t) {
  if (t < T_IGNITION || t >= T_LIFTOFF) return 0;
  return SHAKE_AMP * Math.sin(2 * Math.PI * SHAKE_HZ * t);
}

/**
 * Full launch pose at time t as pure data (no scene graph involved):
 *
 * {
 *   time, phase,                       // 'hold' | 'ignition' | 'ascent' | 'separation'
 *   shake,                             // signed lateral jitter amplitude
 *   rocket:  { x, y, z },              // rocket position (world space)
 *   boosterDetached: boolean,
 *   booster: { x, y, z }               // booster position (world space either way)
 * }
 */
export function launchState(t) {
  const y = altitude(t);
  let phase;
  if (t < T_IGNITION) phase = 'hold';
  else if (t < T_LIFTOFF) phase = 'ignition';
  else if (t < T_SEP) phase = 'ascent';
  else phase = 'separation';

  const sh = shake(t);

  if (t < T_SEP) {
    return {
      time: t,
      phase,
      shake: sh,
      rocket: { x: sh, y, z: -sh },
      boosterDetached: false,
      booster: { x: sh, y: y + BOOSTER_LOCAL_Y, z: -sh },
    };
  }

  // Separation: booster keeps its velocity at t = T_SEP (= SEP_V_Y upward)
  // then flies ballistically; it also drifts downrange (+x).
  const d = t - T_SEP;
  const sepY = altitude(T_SEP); // 75 m
  const yBooster = sepY + SEP_V_Y * d - 0.5 * GRAVITY * d * d;
  return {
    time: t,
    phase,
    shake: sh,
    rocket: { x: 0, y, z: 0 },
    boosterDetached: true,
    booster: { x: SEP_DRIFT_X * d, y: yBooster, z: 0 },
  };
}

// ---------------------------------------------------------------------------
// Scene graph
// ---------------------------------------------------------------------------

/** Launch pad: a "rocket" Group (with a separable "booster" child) + a tower. */
export function buildPad() {
  const pad = new THREE.Group();
  pad.name = 'pad';

  const tower = new THREE.Group();
  tower.name = 'tower';
  tower.position.x = -2;
  const mast = new THREE.Mesh(
    new THREE.BoxGeometry(0.4, 12, 0.4),
    new THREE.MeshBasicMaterial({ color: 0x888888 })
  );
  mast.position.y = 6;
  tower.add(mast);
  pad.add(tower);

  const rocket = new THREE.Group();
  rocket.name = 'rocket';
  const body = new THREE.Mesh(
    new THREE.CylinderGeometry(0.5, 0.5, 4, 16),
    new THREE.MeshBasicMaterial({ color: 0xdddddd })
  );
  body.position.y = 2;
  rocket.add(body);

  const booster = new THREE.Group();
  booster.name = 'booster';
  const skirt = new THREE.Mesh(
    new THREE.CylinderGeometry(0.55, 0.55, 1.2, 16),
    new THREE.MeshBasicMaterial({ color: 0xcc4444 })
  );
  skirt.position.y = BOOSTER_LOCAL_Y;
  booster.add(skirt);
  rocket.add(booster);

  pad.add(rocket);
  return pad;
}

/** Apply the pure pose from launchState(t) to a pad built by buildPad(). */
export function applyLaunch(pad, t) {
  const state = launchState(t);
  const rocket = pad.getObjectByName('rocket');
  rocket.position.set(state.rocket.x, state.rocket.y, state.rocket.z);

  let booster =
    rocket.getObjectByName('booster') ?? pad.getObjectByName('booster');

  // Keep the booster parented according to the timeline (idempotent, so the
  // same pad can be scrubbed back and forth through t = T_SEP).
  if (state.boosterDetached && booster.parent !== pad) {
    pad.attach(booster); // preserves world transform on detach
  } else if (!state.boosterDetached && booster.parent !== rocket) {
    rocket.attach(booster);
  }

  booster.position.set(state.booster.x, state.booster.y, state.booster.z);
  return state;
}
"})
