describe('numeric derivative is continuous at the blend point t = 5.5', () => {
  it('left and right slopes agree within 1e-3', () => {
    const h = 1e-5;
    const left = (alt(T_BLEND) - alt(T_BLEND - h)) / h; // secant of 4s^2 branch
    const right = (alt(T_BLEND + h) - alt(T_BLEND)) / h; // secant of 20s-25 branch
    expect(Math.abs(right - left)).toBeLessThan(1e-3);
  });

  it('both slopes converge on the documented 20 m/s climb rate', () => {
    const h = 1e-4;
    const slope = (alt(T_BLEND + h) - alt(T_BLEND - h)) / (2 * h);
    expect(Math.abs(slope - 20)).toBeLessThan(1e-3);
  });
});

