    const rocket = pad.getObjectByName('rocket');
    const booster = pad.getObjectByName('booster');
    expect(booster.parent).toBe(rocket);
  });

  it('at t = 8.01 the booster is a world-space sibling below the rocket', () => {
    const pad = buildPad();
    applyLaunch(pad, T_SEP + 0.01);

    const rocket = pad.getObjectByName('rocket');
    const booster = pad.getObjectByName('booster');

    // no longer a child of the rocket
    expect(booster.parent).not.toBe(rocket);
    expect(booster.parent).toBe(pad);
    expect(rocket.children.some((c) => c.name === 'booster')).toBe(false);

    // below the rocket in world space
    const rPos = new THREE.Vector3();
    const bPos = new THREE.Vector3();
    rocket.getWorldPosition(rPos);
    booster.getWorldPosition(bPos);
    expect(bPos.y).toBeLessThan(rPos.y);

    // drifting +x
    expect(bPos.x).toBeGreaterThan(rPos.x);
  });

  it('scrubbing back before separation re-attaches the booster', () => {
